      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
      terms: '',
    });

    assert.equal(result.ok, false);
    assert.equal(result.error, 'TERMS_INVALID');
  });
});

describe('lineTotal', () => {
  test('calculates qty times unitPrice', () => {
    const line = { qty: 2, unitPrice: 8500 };
    assert.equal(lineTotal(line), 17000);
  });

  test('handles single unit', () => {
    const line = { qty: 1, unitPrice: 8500 };
    assert.equal(lineTotal(line), 8500);
  });

  test('handles large quantities', () => {
    const line = { qty: 100, unitPrice: 50 };
    assert.equal(lineTotal(line), 5000);
  });
});

describe('lineDiscount', () => {
  test('calculates discount as total × discountPercent / 100', () => {
    const line = { qty: 2, unitPrice: 1000, discountPercent: 50 };
    assert.equal(lineDiscount(line), 1000);
  });

  test('calculates decimal discount correctly', () => {
    const line = { qty: 4, unitPrice: 1000, discountPercent: 12.5 };
    assert.equal(lineDiscount(line), 500);
  });

  test('returns 0 when discountPercent is 0', () => {
    const line = { qty: 10, unitPrice: 500, discountPercent: 0 };
    assert.equal(lineDiscount(line), 0);
  });

  test('returns 0 when discountPercent is not provided', () => {
    const line = { qty: 10, unitPrice: 500 };
    assert.equal(lineDiscount(line), 0);
  });

  test('handles 100% discount', () => {
    const line = { qty: 2, unitPrice: 1000, discountPercent: 100 };
    assert.equal(lineDiscount(line), 2000);
  });
});

describe('lineVAT', () => {
  test('calculates VAT on amount after discount', () => {
    const line = { qty: 2, unitPrice: 1000, vatRate: 21 };
    // Total: 2000, no discount, VAT: 2000 * 21 / 100 = 420
    assert.equal(lineVAT(line), 420);
  });

  test('returns 0 when vatRate is 0', () => {
    const line = { qty: 2, unitPrice: 1000, vatRate: 0 };
    assert.equal(lineVAT(line), 0);
  });

  test('returns 0 when vatRate is not provided', () => {
    const line = { qty: 2, unitPrice: 1000 };
    assert.equal(lineVAT(line), 0);
  });

  test('calculates VAT on discounted amount', () => {
    const line = { qty: 2, unitPrice: 1000, discountPercent: 50, vatRate: 21 };
    // Total: 2000, Discount: 1000, Amount after discount: 1000
    // VAT: 1000 * 21 / 100 = 210
    assert.equal(lineVAT(line), 210);
  });

  test('handles different VAT rates', () => {
    const line9 = { qty: 1, unitPrice: 1000, vatRate: 9 };
    assert.equal(lineVAT(line9), 90);

    const line21 = { qty: 1, unitPrice: 1000, vatRate: 21 };
    assert.equal(lineVAT(line21), 210);
  });

  test('rounds VAT correctly', () => {
    const line = { qty: 3, unitPrice: 100, vatRate: 21 };
    // Total: 300, VAT: 300 * 21 / 100 = 63 (exact, no rounding needed)
    assert.equal(lineVAT(line), 63);
  });

  test('rounds VAT with fractional result', () => {
    const line = { qty: 1, unitPrice: 100, vatRate: 21 };
    // Total: 100, VAT: 100 * 21 / 100 = 21 (exact)
    assert.equal(lineVAT(line), 21);
  });

  test('handles VAT on 0 amount after discount', () => {
    const line = { qty: 1, unitPrice: 1000, discountPercent: 100, vatRate: 21 };
    // Total: 1000, Discount: 1000, Amount after discount: 0, VAT: 0
    assert.equal(lineVAT(line), 0);
  });
});

describe('invoiceTotals', () => {
  test('calculates subtotal, discount, vat and total for single line', () => {
    const invoice = {
      lines: [{ qty: 2, unitPrice: 8500 }],
    };
    const totals = invoiceTotals(invoice);
    assert.deepEqual(totals, { subtotal: 17000, discount: 0, vat: 0, total: 17000 });
  });

  test('calculates subtotal, discount and total for multiple lines', () => {
    const invoice = {
      lines: [
        { qty: 2, unitPrice: 8500 },
        { qty: 3, unitPrice: 9500 },
      ],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 17000 + 28500);
    assert.equal(totals.discount, 0);
    assert.equal(totals.vat, 0);
    assert.equal(totals.total, 17000 + 28500);
  });

  test('equals zero for empty lines', () => {
    const invoice = { lines: [] };
    const totals = invoiceTotals(invoice);
    assert.deepEqual(totals, { subtotal: 0, discount: 0, vat: 0, total: 0 });
  });

  test('works with real invoice from createInvoice', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [
        { sku: 'DES-HOUR', qty: 2 },
        { sku: 'DEV-HOUR', qty: 1 },
      ],
    });

    assert.equal(result.ok, true);
    const totals = invoiceTotals(result.value);
    const subtotal = 2 * 8500 + 1 * 9500;
    const goldDiscount = subtotal * (TIER_DISCOUNTS.gold / 100);
    // VAT is calculated on amount after discount (21% VAT rate for both items)
    const vat = lineVAT(result.value.lines[0]) + lineVAT(result.value.lines[1]);
    assert.equal(totals.subtotal, subtotal);
    assert.equal(totals.discount, goldDiscount);
    assert.equal(totals.vat, vat);
    assert.equal(totals.total, subtotal - goldDiscount + vat);
  });

  test('calculates discount correctly with single line', () => {
    const invoice = {
      lines: [{ qty: 2, unitPrice: 1000, discountPercent: 50 }],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 2000);
    assert.equal(totals.discount, 1000);
    assert.equal(totals.total, 1000);
  });

  test('calculates discount correctly with multiple lines', () => {
    const invoice = {
      lines: [
        { qty: 2, unitPrice: 1000, discountPercent: 50 },
        { qty: 1, unitPrice: 1000, discountPercent: 25 },
      ],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 3000);
    assert.equal(totals.discount, 1250);
    assert.equal(totals.total, 1750);
  });

  test('clamps total to 0 when discount >= subtotal', () => {
    const invoice = {
      lines: [{ qty: 2, unitPrice: 1000, discountPercent: 100 }],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 2000);
    assert.equal(totals.discount, 2000);
    assert.equal(totals.total, 0);
  });

  test('handles mixed lines with and without discounts', () => {
    const invoice = {
      lines: [
        { qty: 1, unitPrice: 1000, discountPercent: 50 },
        { qty: 1, unitPrice: 1000 },
      ],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 2000);
    assert.equal(totals.discount, 500);
    assert.equal(totals.vat, 0);
    assert.equal(totals.total, 1500);
  });

  test('calculates VAT on single line', () => {
    const invoice = {
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 21 }],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 10000);
    assert.equal(totals.vat, 2100);
    assert.equal(totals.total, 12100);
  });

  test('calculates VAT on multiple lines with different rates', () => {
    const invoice = {
      lines: [
        { qty: 1, unitPrice: 10000, vatRate: 21 },
        { qty: 1, unitPrice: 10000, vatRate: 9 },
      ],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 20000);
    assert.equal(totals.vat, 2100 + 900);
    assert.equal(totals.total, 23000);
  });

  test('calculates VAT on amount after discount', () => {
    const invoice = {
      lines: [{ qty: 1, unitPrice: 10000, discountPercent: 10, vatRate: 21 }],
    };
    const totals = invoiceTotals(invoice);
    // Subtotal: 10000, Discount: 1000, Amount after discount: 9000
    // VAT: 9000 * 21 / 100 = 1890
    assert.equal(totals.subtotal, 10000);
    assert.equal(totals.discount, 1000);
    assert.equal(totals.vat, 1890);
    assert.equal(totals.total, 10000 - 1000 + 1890);
  });

  test('sums VAT from multiple lines correctly', () => {
    const invoice = {
      lines: [
        { qty: 1, unitPrice: 10000, vatRate: 21 },
        { qty: 1, unitPrice: 10000, discountPercent: 50, vatRate: 21 },
      ],
    };
    const totals = invoiceTotals(invoice);
    // Line 1: 10000 * 21% = 2100
    // Line 2: (10000 - 5000) * 21% = 5000 * 21% = 1050
    assert.equal(totals.subtotal, 20000);
    assert.equal(totals.discount, 5000);
    assert.equal(totals.vat, 2100 + 1050);
    assert.equal(totals.total, 20000 - 5000 + 3150);
  });

  test('clamps total to 0 when discount and VAT result in negative', () => {
    const invoice = {
      lines: [{ qty: 1, unitPrice: 1000, discountPercent: 100, vatRate: 21 }],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 1000);
    assert.equal(totals.discount, 1000);
    assert.equal(totals.vat, 0);
    assert.equal(totals.total, 0);
  });
});

describe('addLine', () => {
  test('adds a new line to an invoice', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value;

    const result = addLine(invoice, { sku: 'DEV-HOUR', qty: 2 });

    assert.equal(result.ok, true);
    assert.equal(result.value.lines.length, 2);
    assert.equal(result.value.lines[1].sku, 'DEV-HOUR');
    assert.equal(result.value.lines[1].qty, 2);
  });

  test('increments qty if SKU already exists', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 3 }],
    }).value;

    const result = addLine(invoice, { sku: 'DES-HOUR', qty: 2 });

    assert.equal(result.ok, true);
    assert.equal(result.value.lines.length, 1);
    assert.equal(result.value.lines[0].qty, 5);
  });

  test('includes catalogue data for new lines', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value;

    const result = addLine(invoice, { sku: 'DEV-HOUR', qty: 1 });

    assert.equal(result.ok, true);
    const newLine = result.value.lines[1];
    assert.equal(newLine.name, 'Development (hour)');
    assert.equal(newLine.unitPrice, 9500);
    assert.equal(newLine.vatRate, 21);
  });

  test('rejects invalid quantity', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value;

    const result = addLine(invoice, { sku: 'DEV-HOUR', qty: 0 });

    assert.equal(result.ok, false);
    assert.equal(result.error, 'QTY_INVALID');
  });

  test('rejects non-integer quantity', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value;

    const result = addLine(invoice, { sku: 'DEV-HOUR', qty: 1.5 });

    assert.equal(result.ok, false);
    assert.equal(result.error, 'QTY_INVALID');
  });

  test('rejects unknown SKU', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value;

    const result = addLine(invoice, { sku: 'NONEXISTENT', qty: 1 });

    assert.equal(result.ok, false);
    assert.equal(result.error, 'UNKNOWN_SKU');
  });

  test('rejects if invoice is not draft', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value;
    invoice.status = 'sent';

    const result = addLine(invoice, { sku: 'DEV-HOUR', qty: 1 });

    assert.equal(result.ok, false);
    assert.equal(result.error, 'NOT_DRAFT');
  });

  test('does not mutate original invoice', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value;

    addLine(invoice, { sku: 'DEV-HOUR', qty: 1 });

    assert.equal(invoice.lines.length, 1);
  });

  test('adds a new line with discount', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value;

    const result = addLine(invoice, { sku: 'DEV-HOUR', qty: 2, discountPercent: 25 });

    assert.equal(result.ok, true);
    assert.equal(result.value.lines[1].discountPercent, 25);
  });

  test('rejects invalid discount on addLine', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value;

    const result = addLine(invoice, { sku: 'DEV-HOUR', qty: 2, discountPercent: 150 });

    assert.equal(result.ok, false);
    assert.equal(result.error, 'DISCOUNT_INVALID');
  });

  test('applies tier discount when adding line without discountPercent', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value;

    const result = addLine(invoice, { sku: 'DEV-HOUR', qty: 2 });

    assert.equal(result.ok, true);
    assert.equal(result.value.lines[1].discountPercent, TIER_DISCOUNTS.gold);
  });

  test('applies standard tier discount on addLine', () => {
    const invoice = createInvoice({
      customerId: 'C-002',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value;

    const result = addLine(invoice, { sku: 'DEV-HOUR', qty: 2 });

    assert.equal(result.ok, true);
    assert.equal(result.value.lines[1].discountPercent, TIER_DISCOUNTS.standard);
  });

  test('explicit discount overrides tier on addLine', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value;

    const result = addLine(invoice, { sku: 'DEV-HOUR', qty: 2, discountPercent: 15 });

    assert.equal(result.ok, true);
    assert.equal(result.value.lines[1].discountPercent, 15);
  });

  test('explicit discount of 0 overrides tier on addLine', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value;

    const result = addLine(invoice, { sku: 'DEV-HOUR', qty: 2, discountPercent: 0 });

    assert.equal(result.ok, true);
    assert.equal(result.value.lines[1].discountPercent, 0);
  });

  test('does not change discount when incrementing existing line', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 10 }],
    }).value;

    const result = addLine(invoice, { sku: 'DES-HOUR', qty: 2 });

    assert.equal(result.ok, true);
    assert.equal(result.value.lines[0].qty, 3);
    assert.equal(result.value.lines[0].discountPercent, 10);
  });
});

describe('removeLine', () => {
  test('removes a line by SKU', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [
        { sku: 'DES-HOUR', qty: 1 },
        { sku: 'DEV-HOUR', qty: 2 },
      ],
    }).value;

    const result = removeLine(invoice, 'DES-HOUR');

    assert.equal(result.ok, true);
    assert.equal(result.value.lines.length, 1);
    assert.equal(result.value.lines[0].sku, 'DEV-HOUR');
  });

  test('rejects if SKU not found', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value;

    const result = removeLine(invoice, 'NONEXISTENT');

    assert.equal(result.ok, false);
    assert.equal(result.error, 'LINE_NOT_FOUND');
  });

  test('rejects if it would leave no lines', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value;

    const result = removeLine(invoice, 'DES-HOUR');

    assert.equal(result.ok, false);
    assert.equal(result.error, 'NO_LINES');
  });

  test('rejects if invoice is not draft', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [
        { sku: 'DES-HOUR', qty: 1 },
        { sku: 'DEV-HOUR', qty: 1 },
      ],
    }).value;
    invoice.status = 'sent';

    const result = removeLine(invoice, 'DES-HOUR');

    assert.equal(result.ok, false);
    assert.equal(result.error, 'NOT_DRAFT');
  });

  test('does not mutate original invoice', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [
        { sku: 'DES-HOUR', qty: 1 },
        { sku: 'DEV-HOUR', qty: 1 },
      ],
    }).value;

    removeLine(invoice, 'DES-HOUR');

    assert.equal(invoice.lines.length, 2);
  });

  test('can remove from multiple lines', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [
        { sku: 'DES-HOUR', qty: 1 },
        { sku: 'DEV-HOUR', qty: 1 },
        { sku: 'COPY-HOUR', qty: 1 },
      ],
    }).value;

    const result = removeLine(invoice, 'DEV-HOUR');

    assert.equal(result.ok, true);
    assert.equal(result.value.lines.length, 2);
    assert.equal(result.value.lines[0].sku, 'DES-HOUR');
    assert.equal(result.value.lines[1].sku, 'COPY-HOUR');
  });
});

describe('issueInvoice', () => {
  test('assigns number and marks issued', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value;

    const result = issueInvoice(invoice, []);

    assert.equal(result.ok, true);
    assert.equal(result.value.number, 'INV-2026-0001');
    assert.equal(result.value.status, 'issued');
  });

  test('uses existing numbers to determine next', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value;

    const existingNumbers = ['INV-2026-0001', 'INV-2026-0002'];
    const result = issueInvoice(invoice, existingNumbers);

    assert.equal(result.ok, true);
    assert.equal(result.value.number, 'INV-2026-0003');
  });

  test('uses year from issue date', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-06-15',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value;

    const existingNumbers = ['INV-2025-0005'];
    const result = issueInvoice(invoice, existingNumbers);

    assert.equal(result.ok, true);
    assert.equal(result.value.number, 'INV-2025-0006');
  });

  test('rejects if not draft', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value;
    invoice.status = 'issued';

    const result = issueInvoice(invoice, []);

    assert.equal(result.ok, false);
    assert.equal(result.error, 'NOT_DRAFT');
  });

  test('does not mutate original invoice', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value;

    issueInvoice(invoice, []);

    assert.equal(invoice.status, 'draft');
    assert.equal(invoice.number, undefined);
  });

  test('preserves all invoice data', () => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [
        { sku: 'DES-HOUR', qty: 2 },
        { sku: 'DEV-HOUR', qty: 1 },
      ],
    }).value;

    const result = issueInvoice(invoice, []);

    assert.equal(result.ok, true);
    assert.equal(result.value.customerId, 'C-001');
    assert.equal(result.value.issueDate, '2026-10-07');
    assert.equal(result.value.lines.length, 2);
    assert.deepEqual(result.value.lines[0], invoice.lines[0]);
    assert.deepEqual(result.value.lines[1], invoice.lines[1]);
  });
});

